export function getLocalizedProduct(product: Product, locale: SupportedLocale): Product {
  if (locale === 'vi') return product;

  const localizedName = PRODUCT_NAME_TRANSLATIONS[product.id]?.[locale] || product.name;
  
  // Localized description formula
  let localizedDesc = product.shortDesc;
  if (locale === 'zh-CN') {
    localizedDesc = `T&T Vina 官方一级代理原装正品 ${localizedName}，支持越南本地增值税发票与现货极速配送，符合SMT电子制造与精密工业产线技术标准。`;
  } else if (locale === 'en') {
    localizedDesc = `Genuine ${localizedName} distributed by T&T Vina Industrial Co., Ltd, meeting ISO standards for high-precision SMT assembly and automation factories.`;
  } else if (locale === 'de') {
    localizedDesc = `Original ${localizedName}, offiziell vertrieben von T&T Vina Industrial Co., Ltd, erfüllt Industriestandards für SMT- und automatische Montageanlagen.`;
  } else if (locale === 'ko') {
    localizedDesc = `T&T Vina Industrial Co., Ltd 공식 공급 정품 ${localizedName}, SMT 전자 제조 및 자동화 공장 표준을 완벽 충족합니다.`;
  } else if (locale === 'ja') {
    localizedDesc = `T&T Vina Industrial Co., Ltd 正規代理店純正品 ${localizedName}。SMT電子実装および自動化ラインの精密産業規格に準拠。`;
  } else if (locale === 'th') {
    localizedDesc = `สินค้าของแท้ ${localizedName} จัดจำหน่ายโดย T&T Vina Industrial Co., Ltd รองรับมาตรฐานโรงงานประกอบ SMT และระบบอัตโนมัติ`;
  }

  // Localized specs
  const localizedSpecs: Record<string, string> = {};
  if (product.specs) {
    for (const [k, v] of Object.entries(product.specs)) {
      const transK = SPEC_KEY_TRANSLATIONS[k]?.[locale] || k;
      const transV = COMMON_VALUE_TRANSLATIONS[v]?.[locale] || v;
      localizedSpecs[transK] = transV;
    }
  }

  const localizedStockLoc = COMMON_VALUE_TRANSLATIONS[product.stockLocation]?.[locale] || product.stockLocation;

  // Localized Category
  const catKey = product.categorySlug || '';
  const localizedCategory = CATEGORY_TRANSLATIONS[catKey]?.[locale] || product.category;

  // Localized Highlights
  let localizedHighlights = product.highlights;
  if (locale === 'zh-CN') {
    localizedHighlights = [
      '100% 原厂正品保证，提供完整官方原产地及品质合格证明 (CO/CQ)',
      '高耐磨、高精度、适应工业自动化产线 24/7 全天候严苛稳定运行',
      '在越外资企业专项服务：专业技术工程师现场协助安装、调试与试样'
    ];
  } else if (locale === 'en') {
    localizedHighlights = [
      '100% Genuine product with full official CO/CQ certificates',
      'High durability and precision for continuous 24/7 industrial production lines',
      'Comprehensive on-site technical installation, calibration, and delivery support across industrial parks'
    ];
  } else if (locale === 'de') {
    localizedHighlights = [
      '100% Originalware mit vollständigen offiziellen Werksprüfzeugnissen (CO/CQ)',
      'Hohe Belastbarkeit und Präzision für den industriellen 24/7-Dauerbetrieb',
      'Technischer Vor-Ort-Support, Installation und Express-Lieferung in alle Industrieparks'
    ];
  } else if (locale === 'ko') {
    localizedHighlights = [
      '100% 제조사 정품 보장, 공식 원산지(CO) 및 품질(CQ) 인증서 완비',
      '산업용 제조 공정 24/7 연속 가동을 위한 우수한 내구성과 정밀도',
      '베트남 북부/남부 공단 엔지니어 현장 설치, 샘플 테스트 및 기술 지원'
    ];
  } else if (locale === 'ja') {
    localizedHighlights = [
      '100% メーカー正規純正品、原産地証明書(CO)および品質検査書(CQ)完備',
      '24時間連続稼働の過酷な工場環境に耐える高耐久・高精度スペック',
      '各工業団地への即日納入、現地技術者による設置・試運転サポート'
    ];
  } else if (locale === 'th') {
    localizedHighlights = [
      'ของแท้ 100% พร้อมเอกสารรับรองถิ่นกำเนิดและคุณภาพ (CO/CQ) ครบถ้วน',
      'ทนทานสูง แม่นยำ รองรับการทำงานในสายการผลิตอุตสาหกรรมต่อเนื่อง 24/7',
      'บริการจัดส่งด่วนและมีวิศวกรเทคนิคช่วยทดสอบและติดตั้งหน้างาน'
    ];
  }

  return {
    ...product,
    name: localizedName,
    shortDesc: localizedDesc,
    category: localizedCategory,
    specs: localizedSpecs,
    stockLocation: localizedStockLoc,
    highlights: localizedHighlights
  };
}
